<script setup lang="ts">
const props = defineProps<{ ev: any }>(); const toast = useToast()
const { data, refresh } = await useAsyncData(`orders-${props.ev.id}`, () => api<any[]>(`/api/manage/events/${props.ev.id}/orders`), { server: false })
const filter = ref(''); const rows = computed(() => (data.value ?? []).filter((o) => !filter.value || o.channel === filter.value || o.status === filter.value))
const chan: Record<string, string> = { online: 'En ligne', physical: 'Guichet', guest: 'Invité / transfert', import: 'Import' }
const cls = (s: string) => ({ paid: 'text-emerald-300', pending: 'text-amber-300', failed: 'text-red-300', expired: 'text-muted', cancelled: 'text-red-300' }[s] ?? '')
async function cancel(o: any) { const reason = prompt('Motif de l’annulation de cette vente au guichet ?'); if (!reason) return; try { await api(`/api/manage/orders/${o.id}/cancel`, { method: 'POST', body: { reason } }); toast.ok('Vente annulée, places libérées'); refresh() } catch (e) { toast.err(errMsg(e)) } }
</script>
<template>
  <div class="space-y-4"><div class="flex flex-wrap items-center gap-3"><select v-model="filter" class="input max-w-xs" aria-label="Filtrer"><option value="">Toutes les commandes</option><option value="online">En ligne</option><option value="physical">Guichet</option><option value="paid">Payées</option><option value="pending">En attente</option><option value="expired">Expirées</option></select><a class="btn btn-ghost ml-auto" :href="`/api/manage/events/${ev.id}/orders?format=csv`">Exporter les ventes (CSV)</a></div>
    <UiEmpty v-if="!rows.length" title="Aucune commande" text="Les ventes en ligne et au guichet apparaîtront ici." />
    <div v-else class="card overflow-x-auto"><table class="w-full min-w-[820px]"><thead><tr><th class="th">Date</th><th class="th">Canal</th><th class="th">Acheteur</th><th class="th">Billets</th><th class="th">Total</th><th class="th">Net orga.</th><th class="th">Statut</th><th class="th" /></tr></thead>
      <tbody class="divide-y divide-line"><tr v-for="o in rows" :key="o.id"><td class="td whitespace-nowrap text-muted">{{ fdate(o.paidAt || o.createdAt, { dateStyle: 'short', timeStyle: 'short' }) }}</td><td class="td"><span class="chip">{{ chan[o.channel] }}</span><span v-if="o.paymentMethod" class="ml-1 text-xs text-muted">{{ o.paymentMethod }}</span><span v-if="o.campaign && o.channel === 'online'" class="ml-1 text-xs text-muted">#{{ o.campaign }}</span></td><td class="td">{{ o.buyerName }}<span class="block text-xs text-muted">{{ o.channel === 'online' ? o.buyerEmail : o.seller ? `vendu par ${o.seller}` : '' }}</span></td><td class="td">{{ o.tickets }}</td><td class="td font-semibold">{{ money(o.total, ev.currency) }}</td><td class="td">{{ money(o.organizerNet, ev.currency) }}</td><td class="td font-semibold capitalize" :class="cls(o.status)">{{ o.status }}<span v-if="o.isDemo" class="ml-1 text-xs text-amber-300">démo</span></td><td class="td text-right"><button v-if="o.channel === 'physical' && o.status === 'paid'" class="btn btn-danger !min-h-[36px] px-3" @click="cancel(o)">Annuler</button></td></tr></tbody></table></div></div>
</template>
